def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    desperate_count = 0
    rich_count = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                desperate_count += 1
            if opp.get('budget', 0) > 700:
                rich_count += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(prev.get('bid', 0))

    if not alive:
        safe_bid = min(budget, 18.0)
        if hp <= 3 or no_water_days >= 1:
            safe_bid = min(budget, 32.0)
        return max(0.0, float(safe_bid))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = (sum(prev_bids) / float(len(prev_bids))) if prev_bids else 0.0

    supply_pressure = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if supply_pressure < 0:
        supply_pressure = 0.0
    if supply_pressure > 1:
        supply_pressure = 1.0

    urgency = 0.0
    if hp <= 2:
        urgency += 1.0
    elif hp <= 4:
        urgency += 0.55
    if no_water_days >= 2:
        urgency += 1.0
    elif no_water_days >= 1:
        urgency += 0.45

    market_pressure = min(1.0, highest_prev / 100.0)

    base = 18.0 + 20.0 * supply_pressure + 10.0 * market_pressure + 8.0 * min(1.0, desperate_count / 3.0)

    if urgency >= 1.5:
        bid = max(base + 18.0, highest_prev * 0.96 + 2.0, 62.0)
    elif urgency >= 0.7:
        bid = max(base + 8.0, avg_prev * 0.72 + 2.0, 38.0)
    else:
        bid = max(base, avg_prev * 0.45 + 1.0)

    if supply >= 23 and urgency < 0.7:
        bid *= 0.72
    elif supply >= 20 and urgency < 0.7:
        bid *= 0.84
    elif supply <= 17:
        bid *= 1.18

    if rich_count >= 2 and supply <= 18:
        bid += 6.0

    if day >= 8:
        bid *= 1.08
    if day >= 9 and (hp <= 4 or no_water_days >= 1):
        bid *= 1.12

    reserve = 0.0
    days_left = max(0, 10 - day)
    if hp > 4 and no_water_days == 0:
        reserve = min(budget * 0.45, days_left * 10.0)
    elif hp > 2:
        reserve = min(budget * 0.25, days_left * 6.0)

    cap = max(0.0, budget - reserve)
    if urgency >= 1.5:
        cap = budget
    elif urgency >= 0.7:
        cap = max(cap, budget * 0.7)

    bid = min(bid, cap)
    bid = min(bid, budget)
    bid = max(0.0, bid)

    if budget < 25 and urgency < 1.5:
        bid = min(bid, max(8.0, budget * 0.7))

    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    my_hp = int(my_status.get('hp', 0))
    my_budget = float(my_status.get('budget', 0.0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        try:
            if opp.get('alive', False):
                alive_opponents.append((opp_id, opp))
        except Exception:
            continue

    if not alive_opponents:
        return float(min(my_budget, DAILY_SALARY * 0.4))

    # Extract yesterday bids from previous_trace only
    yesterday_bids = []
    for opp_id, opp in alive_opponents:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    # Determine pressure level from yesterday
    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0
    avg_prev_bid = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 0.0

    # Supply-aware baseline: if supply is tight near MIN, increase bid to avoid losing allocation
    # Use a simple scaling between 15 and 25.
    if MAX_SUPPLY > MIN_SUPPLY:
        tightness = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    else:
        tightness = 0.5
    tightness = max(0.0, min(1.0, tightness))

    # If we are in danger (low HP or already no-water days), prioritize survival
    if my_hp <= 2 or my_no_water_days >= 2:
        target = DAILY_SALARY * (0.85 + 0.1 * tightness)
    elif my_hp <= 3:
        target = DAILY_SALARY * (0.65 + 0.15 * tightness)
    else:
        # Match the high cluster if someone paid aggressively yesterday.
        # If highest is very high, bid slightly below it to win with less cost.
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            target = min(highest_prev_bid - 2.0, DAILY_SALARY * (0.75 + 0.1 * tightness))
        else:
            # Otherwise, bid around the average of yesterday but slightly boosted for tight supply.
            target = avg_prev_bid * 0.9 + DAILY_SALARY * 0.1 + DAILY_SALARY * 0.08 * tightness

    # Convert target into a safe bid within budget
    # Also ensure bid is not trivially low when supply is tight.
    min_floor = DAILY_SALARY * (0.35 + 0.2 * tightness)
    bid = max(min_floor, target)
    bid = float(min(my_budget, bid))

    # If budget is extremely low, still bid something proportional
    if bid <= 0.0:
        bid = float(min(my_budget, DAILY_SALARY * 0.1))

    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        # If no opponents, bid low to save budget.
        return min(my_status['budget'], DAILY_SALARY * 0.3)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    # If there are yesterday bids, react to the highest pressure
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        # Check if the highest previous bid indicates high competition (above typical opponent max)
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            if my_status['hp'] > 3:
                # HP is good, but competition is very high, try to outbid but conserve if possible
                # Bid just above highest_prev_bid, but capped to avoid overspending unnecessarily.
                # This ensures competitiveness against very high bids.
                return min(my_status['budget'], max(DAILY_SALARY * 0.5, highest_prev_bid + 1.5))
            else:
                # HP is low, must win, bid very aggressively
                return min(my_status['budget'], DAILY_SALARY * 0.95)
        else:
            # Yesterday's highest bid was moderate, bid slightly above it to secure water
            # but don't overspend. This covers opponent's average and max bids.
            return min(my_status['budget'], max(DAILY_SALARY * 0.5, highest_prev_bid + 1.5))

    # Fallback if no yesterday bids or only low bids from yesterday
    # This part is also for the first day, or if all opponents are new or didn't bid yesterday.
    if my_status['hp'] <= 2:
        # Very low HP, must win
        return min(my_status['budget'], DAILY_SALARY * 0.9)

    # Default bid when HP is good and no strong signal from yesterday
    # This is a competitive bid, around opponent's average.
    return min(my_status['budget'], DAILY_SALARY * 0.55)

